import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.D7EuCHIT.js";const u=JSON.parse('{"title":"服务消息调用","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/service-call.md","filePath":"plugins/service-call.md","lastUpdated":1795335288000}'),r={name:"plugins/service-call.md"};function c(t,e,s,d,n,_){return l(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="服务消息调用" tabindex="-1">服务消息调用 <a class="header-anchor" href="#服务消息调用" aria-label="Permalink to &quot;服务消息调用&quot;">​</a></h1><p><code>LYRA_INTERFACE_SERVICE_CALL</code>（28，<code>plugin/service_call_contracts.h</code>）是宿主帧线程上的<strong>同步类型化端点分发</strong>：按服务句柄和消息接口 ID 调用任意已选中服务，不需要该服务的私有符号。</p><h2 id="结构" tabindex="-1">结构 <a class="header-anchor" href="#结构" aria-label="Permalink to &quot;结构&quot;">​</a></h2><p><code>LyraServiceCallV3</code> 只有 <code>size/version/user/request</code>。C++ 调用方使用内联助手 <code>lyra_service_call(api, handle, interface_id, message, reply)</code> 构造信封，不必手写协议胶水。</p><ul><li><code>HANDLE</code>：注册表中的活动能力句柄；</li><li><code>INTERFACE</code>：已分配的消息接口 ID；</li><li><code>MESSAGE</code>：恰好 <code>sizeof(LyraMessageV3)</code> 的字节，先复制再校验。</li></ul><p>分发会在 query 与 request 期间建立目标所有权、阻止活跃实现被卸载，并校验 reply。冻结（非消息）接口不会被重新解释为消息端点。</p><h2 id="信封语义" tabindex="-1">信封语义 <a class="header-anchor" href="#信封语义" aria-label="Permalink to &quot;信封语义&quot;">​</a></h2><p>MESSAGE 的字段表与数据只在本次调用期间借用——<strong>这不是线格式或文件格式</strong>，不能序列化、落盘或延迟执行。嵌套 MESSAGE 只用于本进程同步调用。返回字段借用到下一次调用前，插件须立即复制需要的数据。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li>插件互相调用：拿到对方服务句柄后按接口 ID 发消息；</li><li>宿主端点调用：对 <code>system.*</code> 等内置服务做类型化请求；</li><li>自定义服务间编排：不走 capability 名字分支。</li></ul><h2 id="约束" tabindex="-1">约束 <a class="header-anchor" href="#约束" aria-label="Permalink to &quot;约束&quot;">​</a></h2><ul><li>帧线程同步调用；不要在音频回调或工作线程里调用；</li><li><code>size==sizeof</code>、version、句柄有效性都严格校验，失败返回 <code>LYRA_MESSAGE_INVALID</code>；</li><li>调用是同步的——目标服务慢会阻塞帧线程，耗时工作应放在对方的异步接口里。</li></ul>',12)])])}const p=a(r,[["render",c]]);export{u as __pageData,p as default};
